import data from './timeline.json';

// Generated by scripts/voiceover.py from narration.json — the single source of timing.
export const TL = data;
export type Line = (typeof data.lines)[number];

const lines = Object.fromEntries(data.lines.map((l) => [l.id, l]));

/** Scene-local frame where a narration line starts. */
export const L = (id: string) => {
	if (!lines[id]) throw new Error(`no line ${id}`);
	return lines[id].local;
};

/** Scene-local frame where the nth occurrence of a spoken word starts. */
export const W = (id: string, word: string, nth = 0) => {
	const l = lines[id];
	const hits = l.words.filter((w) => w.w.toLowerCase().replace(/[,.?!:;]/g, '') === word.toLowerCase());
	if (!hits[nth]) throw new Error(`no word "${word}" #${nth} in ${id}`);
	return l.local + hits[nth].f;
};

/** Scene-local frame where a line ends. */
export const E = (id: string) => lines[id].local + lines[id].dur;
